(function() {
    'use strict';

    class AgenticEnterpriseAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'The Agentic Enterprise';
            this.version = '1.1.0';

            this.ROUNDS = [
                {
                    titleKey: 'round1_title',
                    titleDefault: 'Round 1: The Audit',
                    briefing: '<b>Month 12 of the Agentic Operations Transformation.</b> You are Andres Castellanos, newly appointed COO of Seguros Andinos S.A. — a $920M premium LATAM insurer with 3,400 employees across Colombia, Peru, and Chile.<br><br>An independent operational audit of your AI agent portfolio has revealed troubling findings:<br><br><b>ClaimBot:</b> 94.7% accuracy (below 97.2% industry benchmark). The model underestimates repair costs by 18% on recent claims due to construction cost inflation not reflected in training data. Approximately 4,200 policyholders may have been underpaid.<br><br><b>UnderwriteAI:</b> Rural small business applicants are declined at 2.4x the rate of urban applicants with similar risk profiles — potential geographic discrimination.<br><br><b>ServAI:</b> Customer NPS of 62 (target: 75). Fails on emotionally sensitive interactions. 23% escalation rate (target: 10%).<br><br><b>ComplianceAgent:</b> 99.1% accuracy but auto-responded to 3 regulatory inquiries without adequate substance.<br><br><b>HireAssist:</b> Pilot showing potential language bias favoring native Spanish speakers.<br><br><b>The board audit committee needs your 60-day response plan. Choose TWO priority areas for immediate funding:</b><br>A — Emergency ClaimBot recalibration (halt automated processing)<br>B — Continuous monitoring dashboard for all agents<br>C — Reskilling program for 200 employees<br>D — Proactive regulatory engagement with SFC<br>E — External fairness audit of UnderwriteAI and HireAssist',
                    d1Label: 'First Priority Area',
                    d2Label: 'Second Priority Area',
                    d1LabelKey: 'd1_label_r1',
                    d2LabelKey: 'd2_label_r1',
                    showD2: true,
                    options1: [
                        { value: 'A', text: 'A - Emergency ClaimBot Recalibration' },
                        { value: 'B', text: 'B - Continuous Monitoring Dashboard' },
                        { value: 'C', text: 'C - Employee Reskilling Program' },
                        { value: 'D', text: 'D - Proactive SFC Engagement' },
                        { value: 'E', text: 'E - Fairness Audit (UnderwriteAI + HireAssist)' }
                    ],
                    options2: [
                        { value: 'A', text: 'A - Emergency ClaimBot Recalibration' },
                        { value: 'B', text: 'B - Continuous Monitoring Dashboard' },
                        { value: 'C', text: 'C - Employee Reskilling Program' },
                        { value: 'D', text: 'D - Proactive SFC Engagement' },
                        { value: 'E', text: 'E - Fairness Audit (UnderwriteAI + HireAssist)' }
                    ]
                },
                {
                    titleKey: 'round2_title',
                    titleDefault: 'Round 2: The Scale Error',
                    briefing: '<b>The ClaimBot problem is far worse than initially estimated.</b><br><br>A full 6-month audit reveals 12,400 claims were systematically underpaid across three Colombian provinces — totaling <b>$34.7M USD</b> in underpayments (averaging $2,800 per claim).<br><br>This is now a material financial event, a customer harm crisis, and a potential regulatory enforcement trigger.<br><br><b>Stakeholder Pressures:</b><br>- CFO wants to settle only with the 890 policyholders who have formally complained<br>- Legal counsel recommends minimal disclosure<br>- CEO is worried about the investor day narrative in 4 months<br>- Consumer affairs team believes all 12,400 deserve proactive compensation<br><br><b>Choose your remediation strategy AND your human oversight architecture for the ClaimBot relaunch:</b>',
                    d1Label: 'Remediation Strategy',
                    d2Label: 'Oversight Architecture',
                    d1LabelKey: 'd1_label_r2',
                    d2LabelKey: 'd2_label_r2',
                    showD2: true,
                    options1: [
                        { value: 'A', text: 'A - Reactive only (compensate 890 complainants)' },
                        { value: 'B', text: 'B - Full proactive (all 12,400; $34.7M impact)' },
                        { value: 'C', text: 'C - Tiered (proactive for >$5K; disclose to SFC)' },
                        { value: 'D', text: 'D - Pause ClaimBot entirely; full remediation + disclosure to all regulators' },
                        { value: 'E', text: 'E - Pilot one province first, then decide' }
                    ],
                    options2: [
                        { value: '1', text: '1 - Fully automated + automated monitoring' },
                        { value: '2', text: '2 - Human spot-checks on 5% of claims' },
                        { value: '3', text: '3 - Human review for claims >$15K; auto below' },
                        { value: '4', text: '4 - Human review on all claims (AI as advisor)' },
                        { value: '5', text: '5 - AI processes + policyholder can request human review' }
                    ]
                },
                {
                    titleKey: 'round3_title',
                    titleDefault: 'Round 3: The Workforce Reckoning',
                    briefing: '<b>Month 18. The Workforce Health Index has dropped to 44 — a crisis.</b><br><br>340 positions eliminated (200 beyond plan through non-backfilling). 61% of cuts fell on Lima operations (disproportionately affecting Peruvian workforce). The union (FNTS, 1,100 members) has filed a complaint alleging failure to consult before substantial role changes — a legal requirement under Peruvian labor law.<br><br>Employee survey: 67% believe their job is at risk; 54% say managers have not discussed role changes; 41% of top performers have been approached by competitors.<br><br>The board wants 280 additional reductions via early retirement to hit the 35% cost target. The CEO wants it done before investor day.<br><br><b>Choose your workforce transition strategy:</b><br><br>Option 1 (Accelerated): 60-day VERI, minimal reskilling, legal defense in Peru, no new roles<br>Option 2 (Balanced): 6-month timeline, $2.4M reskilling for 180 people, dialogue with union, 85 new AI oversight roles<br>Option 3 (Deliberate): 12-month VERI only, $4.8M reskilling + income guarantee, suspend Peru changes pending consultation, 140 new roles',
                    d1Label: 'Workforce Strategy',
                    d2Label: '',
                    d1LabelKey: 'd1_label_r3',
                    d2LabelKey: '',
                    showD2: false,
                    options1: [
                        { value: '1', text: '1 - Accelerated (60-day, cost-first)' },
                        { value: '2', text: '2 - Balanced (6-month, reskilling + dialogue)' },
                        { value: '3', text: '3 - Deliberate (12-month, people-first)' }
                    ],
                    options2: []
                },
                {
                    titleKey: 'round4_title',
                    titleDefault: 'Round 4: The Regulatory Confrontation',
                    briefing: '<b>Month 20. The SFC issues Circular Externa 012/2026</b> — new rules for AI in insurance claims, effective in 90 days:<br><br>1. Human review required for all automated settlements above 50 SMMLV (~$18,500 USD)<br>2. Public AI Model Disclosure on company website<br>3. Plain-language explanation for all automated claim denials<br>4. Designated Responsible AI Officer accountable to SFC<br><br>Impact: 38% of claims by value (12% by volume) now need human approval — reversing significant efficiency gains. The deadline coincides with investor day.<br><br>The CEO wants to challenge the regulation. He asks you to prepare a legal challenge, seek deadline extensions, and find minimal compliance paths.<br><br><b>Choose your regulatory response AND your operational compliance architecture:</b>',
                    d1Label: 'Regulatory Response',
                    d2Label: 'Compliance Architecture',
                    d1LabelKey: 'd1_label_r4',
                    d2LabelKey: 'd2_label_r4',
                    showD2: true,
                    options1: [
                        { value: 'A', text: 'A - Legal challenge (seek injunction to delay)' },
                        { value: 'B', text: 'B - Industry coalition (request 6-month extension)' },
                        { value: 'C', text: 'C - Proactive compliance (full compliance as differentiator)' },
                        { value: 'D', text: 'D - Technical compliance (minimum changes, letter of the law)' }
                    ],
                    options2: [
                        { value: 'A', text: 'A - Dedicated 32-FTE human review team' },
                        { value: 'B', text: 'B - ClaimBot recommends, human approves (4h SLA)' },
                        { value: 'C', text: 'C - Explainability-enhanced AI-assisted human review' },
                        { value: 'D', text: 'D - 10% audit sampling (argue this satisfies requirement)' }
                    ]
                },
                {
                    titleKey: 'round5_title',
                    titleDefault: 'Round 5: The Expansion Decision',
                    briefing: '<b>Month 23. Investor day is in two weeks.</b><br><br>Phase 1 final results: OCI ' + String.fromCharCode(8212) + ' improved but below target. SQS ' + String.fromCharCode(8212) + ' improving. WHI ' + String.fromCharCode(8212) + ' recovering from crisis. RCS ' + String.fromCharCode(8212) + ' back above threshold. Cumulative ROI ' + String.fromCharCode(8212) + ' well below the 340% board target due to remediation, compliance, and reskilling costs.<br><br>The CEO needs a Phase 2 narrative. Three options:<br><br><b>A - Actuarial Agent:</b> Deploy AI for actuarial pricing. High potential ($12M/year value), high regulatory complexity, 14-month timeline.<br><br><b>B - Agent Platform Monetization:</b> License your agent infrastructure as B2B service to regional insurers. $8-15M revenue potential, but requires new business capabilities.<br><br><b>C - Governance and Consolidation:</b> Pause new agents for 12 months. Invest in monitoring infrastructure, EU AI Act readiness, ISO 42001 certification. Position as responsible AI leader in LATAM.<br><br>The board audit committee also asks: <i>How do we know when an AI agent should be taken offline?</i>',
                    d1Label: 'Phase 2 Strategy',
                    d2Label: '',
                    d1LabelKey: 'd1_label_r5',
                    d2LabelKey: '',
                    showD2: false,
                    options1: [
                        { value: 'A', text: 'A - Actuarial Agent (high potential, high risk)' },
                        { value: 'B', text: 'B - Platform Monetization (new business model)' },
                        { value: 'C', text: 'C - Governance Consolidation (disciplined foundation)' }
                    ],
                    options2: []
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    oci: 79,
                    sqs: 71,
                    whi: 52,
                    rcs: 74,
                    roi: 127,
                    ociHistory: [],
                    sqsHistory: [],
                    whiHistory: [],
                    rcsHistory: [],
                    roiHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    decision1: 'A',
                    decision2: 'A'
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var sel1 = document.getElementById('decision1Select');
            if (sel1) decisions.decision1 = sel1.value;

            var sel2 = document.getElementById('decision2Select');
            var d2Group = document.getElementById('decision2Group');
            if (sel2 && d2Group && d2Group.style.display !== 'none') {
                decisions.decision2 = sel2.value;
            } else {
                decisions.decision2 = '';
            }

            var currentState = window.mySimulation.state;
            var roundIdx = Math.min((currentState.currentPeriod || 1) - 1, this.ROUNDS.length - 1);

            if (roundIdx === 0 && decisions.decision1 === decisions.decision2) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('same_priority_warning'), 'warning'
                );
                return false;
            }

            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var round = state.currentPeriod;

            var ociDelta = 0;
            var sqsDelta = 0;
            var whiDelta = 0;
            var rcsDelta = 0;
            var roiDelta = 0;

            if (round === 1) {
                var picks = [d.decision1, d.decision2];
                if (picks.indexOf('A') !== -1) { ociDelta += 6; sqsDelta += 8; rcsDelta += 7; roiDelta -= 12; }
                if (picks.indexOf('B') !== -1) { sqsDelta += 4; rcsDelta += 4; roiDelta -= 5; }
                if (picks.indexOf('C') !== -1) { ociDelta += 3; sqsDelta += 3; whiDelta += 8; roiDelta -= 8; }
                if (picks.indexOf('D') !== -1) { rcsDelta += 9; roiDelta -= 3; }
                if (picks.indexOf('E') !== -1) { rcsDelta += 6; whiDelta += 4; roiDelta -= 6; }
                if (picks.indexOf('A') === -1) { sqsDelta -= 5; rcsDelta -= 4; }
            }

            if (round === 2) {
                var rem = d.decision1;
                if (rem === 'A') { rcsDelta -= 3; roiDelta += 8; }
                if (rem === 'B') { sqsDelta += 7; rcsDelta += 5; whiDelta += 3; roiDelta -= 18; ociDelta += 4; }
                if (rem === 'C') { sqsDelta += 5; rcsDelta += 7; roiDelta -= 10; ociDelta += 2; }
                if (rem === 'D') { sqsDelta += 9; rcsDelta += 9; whiDelta += 2; roiDelta -= 25; ociDelta += 8; }
                if (rem === 'E') { sqsDelta += 2; rcsDelta += 1; roiDelta -= 4; }

                var arch = d.decision2;
                if (arch === '1') { roiDelta += 5; rcsDelta += 2; }
                if (arch === '2') { ociDelta += 2; rcsDelta += 4; roiDelta -= 3; }
                if (arch === '3') { ociDelta += 4; rcsDelta += 7; roiDelta -= 8; }
                if (arch === '4') { ociDelta += 10; rcsDelta += 9; roiDelta -= 20; }
                if (arch === '5') { ociDelta += 1; rcsDelta += 8; sqsDelta += 4; roiDelta -= 4; }
            }

            if (round === 3) {
                var strat = d.decision1;
                if (strat === '1') { ociDelta -= 12; whiDelta -= 10; rcsDelta -= 6; roiDelta += 22; sqsDelta -= 3; }
                if (strat === '2') { ociDelta -= 6; whiDelta += 10; rcsDelta += 5; roiDelta += 8; sqsDelta += 3; }
                if (strat === '3') { ociDelta -= 2; whiDelta += 16; rcsDelta += 8; roiDelta -= 4; sqsDelta += 2; }
            }

            if (round === 4) {
                var reg = d.decision1;
                if (reg === 'A') { rcsDelta -= 12; roiDelta -= 8; ociDelta -= 2; }
                if (reg === 'B') { rcsDelta += 3; roiDelta -= 5; ociDelta += 2; }
                if (reg === 'C') { rcsDelta += 10; sqsDelta += 5; roiDelta -= 10; ociDelta += 4; whiDelta += 3; }
                if (reg === 'D') { rcsDelta += 1; roiDelta -= 3; }

                var comp = d.decision2;
                if (comp === 'A') { ociDelta += 6; rcsDelta += 6; roiDelta -= 12; }
                if (comp === 'B') { ociDelta += 3; rcsDelta += 7; roiDelta -= 6; sqsDelta += 2; }
                if (comp === 'C') { ociDelta += 3; rcsDelta += 8; roiDelta -= 7; sqsDelta += 4; }
                if (comp === 'D') { ociDelta += 1; rcsDelta -= 4; roiDelta -= 2; }
            }

            if (round === 5) {
                var exp = d.decision1;
                if (exp === 'A') { roiDelta += 15; ociDelta -= 3; rcsDelta -= 5; sqsDelta += 2; }
                if (exp === 'B') { roiDelta += 10; ociDelta -= 1; whiDelta += 2; }
                if (exp === 'C') { rcsDelta += 10; whiDelta += 8; sqsDelta += 5; roiDelta -= 5; ociDelta += 2; }
            }

            ds.oci = Math.max(0, Math.min(100, ds.oci + ociDelta));
            ds.sqs = Math.max(0, Math.min(100, ds.sqs + sqsDelta));
            ds.whi = Math.max(0, Math.min(100, ds.whi + whiDelta));
            ds.rcs = Math.max(0, Math.min(100, ds.rcs + rcsDelta));
            ds.roi = Math.max(0, ds.roi + roiDelta);

            ds.ociHistory.push(ds.oci);
            ds.sqsHistory.push(ds.sqs);
            ds.whiHistory.push(ds.whi);
            ds.rcsHistory.push(ds.rcs);
            ds.roiHistory.push(ds.roi);

            var results = {
                period: round,
                decision1: d.decision1,
                decision2: d.decision2,
                oci: ds.oci,
                sqs: ds.sqs,
                whi: ds.whi,
                rcs: ds.rcs,
                roi: ds.roi,
                ociDelta: ociDelta,
                sqsDelta: sqsDelta,
                whiDelta: whiDelta,
                rcsDelta: rcsDelta,
                roiDelta: roiDelta
            };

            var nextPeriod = (state.currentPeriod || 1) + 1;
            if (nextPeriod <= (state.maxPeriods || this.ROUNDS.length)) {
                this._updateBriefing({ currentPeriod: nextPeriod });
            }

            return results;
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('ociDisplay', 'domainState.oci', function(v) { return Math.round(v); });
            uiManager.bind('sqsDisplay', 'domainState.sqs', function(v) { return Math.round(v); });
            uiManager.bind('whiDisplay', 'domainState.whi', function(v) { return Math.round(v); });
            uiManager.bind('rcsDisplay', 'domainState.rcs', function(v) { return Math.round(v); });
            uiManager.bind('roiDisplay', 'domainState.roi', function(v) { return Math.round(v) + '%'; });
        }

        getChartConfig() {
            return {
                dashboardChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: 'OCI',
                                data: [],
                                borderColor: '#3498db',
                                backgroundColor: 'rgba(52,152,219,0.1)',
                                borderWidth: 2,
                                fill: false,
                                tension: 0.2
                            },
                            {
                                label: 'SQS',
                                data: [],
                                borderColor: '#27ae60',
                                backgroundColor: 'rgba(39,174,96,0.1)',
                                borderWidth: 2,
                                fill: false,
                                tension: 0.2
                            },
                            {
                                label: 'WHI',
                                data: [],
                                borderColor: '#e67e22',
                                backgroundColor: 'rgba(230,126,34,0.1)',
                                borderWidth: 2,
                                fill: false,
                                tension: 0.2
                            },
                            {
                                label: 'RCS',
                                data: [],
                                borderColor: '#8e44ad',
                                backgroundColor: 'rgba(142,68,173,0.1)',
                                borderWidth: 2,
                                fill: false,
                                tension: 0.2
                            },
                            {
                                label: 'ROI %',
                                data: [],
                                borderColor: '#c0392b',
                                backgroundColor: 'rgba(192,57,43,0.1)',
                                borderWidth: 2,
                                fill: false,
                                tension: 0.2,
                                borderDash: [5, 5]
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Dashboard Metrics Over Rounds' }
                        },
                        scales: {
                            y: { beginAtZero: true, max: 200, title: { display: true, text: 'Score / %' } }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var labels = state.domainState.ociHistory.map(function(_, i) { return 'R' + (i + 1); });
            return {
                dashboardChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.ociHistory },
                        { data: state.domainState.sqsHistory },
                        { data: state.domainState.whiHistory },
                        { data: state.domainState.rcsHistory },
                        { data: state.domainState.roiHistory }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1];
            var r = last.results || {};

            var oci = r.oci || 0;
            var sqs = r.sqs || 0;
            var whi = r.whi || 0;
            var rcs = r.rcs || 0;
            var roi = r.roi || 0;

            var balanced = (sqs * 0.25) + (whi * 0.25) + (rcs * 0.20) + ((100 - oci) * 0.15) + (Math.min(roi, 100) * 0.15);

            var performance = 'Developing Leader';
            if (balanced > 55) performance = 'Competent COO';
            if (balanced > 68) performance = 'Strong Operational Leader';
            if (balanced > 78) performance = 'Exceptional AI Operations Executive';

            var insights = [];
            if (sqs >= 80) insights.push('Strong commitment to service quality and customer protection.');
            if (sqs < 70) insights.push('Service quality needs attention - customer harm may be ongoing.');
            if (whi >= 60) insights.push('Workforce health was maintained through the transformation.');
            if (whi < 50) insights.push('Workforce health deteriorated significantly - organizational trust is damaged.');
            if (rcs >= 80) insights.push('Regulatory relationships are solid - proactive compliance paid off.');
            if (rcs < 70) insights.push('Regulatory exposure remains a concern.');
            if (roi > 150) insights.push('Strong financial returns from the agent portfolio.');
            if (roi < 100) insights.push('Agent portfolio ROI is below investment threshold - remediation costs were significant.');

            return {
                finalOCI: oci,
                finalSQS: sqs,
                finalWHI: whi,
                finalRCS: rcs,
                finalROI: roi,
                balancedScore: Math.round(balanced),
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            var round = results.period;
            if (round === 1 && results.rcsDelta < 0) return window.mySimulation.t('hint_reg_risk');
