            if (round === 3 && results.whiDelta < 0) return window.mySimulation.t('hint_workforce_crisis');
            if (round === 4 && results.rcsDelta < 0) return window.mySimulation.t('hint_reg_challenge');
            if (round === 5) return window.mySimulation.t('hint_final');
            return null;
